    private void btnCalculateActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnCalculateActionPerformed
        Notas grade = new Notas();
        // con este if no se calculan los resultados con datos vacios
        if (!this.getInputGrades(grade)) {
            return;
        }

        // set results
        this.txtMean.setText(String.valueOf(String.format("%.2f", grade.calculateMean())));
        this.txtDevitaion.setText(String.valueOf(String.format("%.2f", grade.calculateDeviation())));
        this.txtMaxGrade.setText(String.valueOf(String.format("%.2f", grade.getMaxGrade())));
        this.txtMinGrade.setText(String.valueOf(String.format("%.2f", grade.getMinGrade())));


    }//GEN-LAST:event_btnCalculateActionPerformed

