    private boolean getInputGrades(Notas grades) {
        // este if evita que aparezcan 5 ventanas de dialogos a la vez.
        if (!this.parseInputs(grades, 0, txtGrade1)) {
            return false;
        }
        if (!this.parseInputs(grades, 1, txtGrade2)) {
            return false;
        }
        if (!this.parseInputs(grades, 2, txtGrade3)) {
            return false;
        }
        if (!this.parseInputs(grades, 3, txtGrade4)) {
            return false;
        }
        if (!this.parseInputs(grades, 4, txtGrade5)) {
            return false;
        }
        return true;
    }

    private boolean parseInputs(Notas grades, int index, javax.swing.JTextField txtGrade) {
        if (txtGrade.getText().equals("")) {
            JOptionPane.showMessageDialog(this, "Ingresa todas las 5 notas");
            txtGrade.requestFocus();
            return false;
        } else {
            try {

                grades.gradeLst[index] = Double.parseDouble(txtGrade.getText());
                return true;
            } catch (NumberFormatException e) {
                JOptionPane.showMessageDialog(this, "Ingresa una nota válida");
                txtGrade.requestFocus();
                return false;
            }
        }
    }

